function deterministicTraineePerson(cohort,idx){let fi=(cohort*7+idx*5)%AUTO_TRAINEE_FIRST.length,li=(cohort*11+idx*9)%AUTO_TRAINEE_LAST.length,first=AUTO_TRAINEE_FIRST[fi],last=AUTO_TRAINEE_LAST[li],age=16+((cohort+idx)%3),year=cohort-age,month=2+((idx*3+cohort)%6),day=3+((idx*7+cohort)%24);return{first,last,birth:ymdUTC(year,month,day),start:`${cohort}-08-01`,standort:["Mitte","Spryndorf","Hechem"][idx%3]}}
async function ensureStaticBirthdaysAndRetirement(env){return true}
async function createAutomaticCohort(env,cohort,count=8){let existing=await env.DB.prepare(`SELECT COUNT(*) c FROM employee_training WHERE cohort_year=?`).bind(cohort).first();if(Number(existing?.c||0)>0)return 0;let created=0,now=new Date().toISOString();for(let i=0;i<count;i++){let person=deterministicTraineePerson(cohort,i),candidate=`${person.first} ${person.last}`,n=1;while(DATA.employees.some(e=>e.name===candidate)){candidate=`${person.first} ${person.last}${++n}`}let [first,...rest]=candidate.split(" "),last=rest.join(" "),id=await nextEmployeeId(env),ret=retirementDateFor(person.birth);await env.DB.prepare(`INSERT INTO employee_records(employee_id,first_name,last_name,name,position,business_area,location,employment,hours,birth_date,start_date,created_at,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(id,first,last,candidate,"Auszubildende/r Fachkraft im Fahrbetrieb · 1. Lehrjahr","Ausbildung",person.standort,"Ausbildung",39,person.birth,person.start,now,"automation-azubi").run();await env.DB.prepare(`INSERT INTO employee_lifecycle(employee_id,birth_date,start_date,end_date,end_reason,updated_at,updated_by) VALUES(?,?,?,?,?,?,?)`).bind(id,person.birth,person.start,ret,"Rente",now,"automation-azubi").run();await env.DB.prepare(`INSERT INTO employee_training(employee_id,cohort_year,program,auto_created,graduated_at,created_at) VALUES(?,?,?,1,NULL,?)`).bind(id,cohort,"Fachkraft im Fahrbetrieb",now).run();created++}await hydrateEmployees(env,true);for(const e of DATA.employees.filter(x=>Number(x.apprenticeCohort)===cohort)){let u=await env.DB.prepare(`SELECT username FROM users WHERE employee_id=?`).bind(e.id).first();if(!u)await createInitialUserForEmployee(e,env)}return created}
async function processApprenticeGraduations(env,today=new Date()){let rows=await env.DB.prepare(`SELECT employee_id,cohort_year,graduated_at FROM employee_training`).all(),todayKey=dateKey(today),now=new Date().toISOString();for(const r of rows.results||[]){let grad=`${Number(r.cohort_year)+3}-08-01`;if(todayKey>=grad&&!r.graduated_at){await env.DB.prepare(`UPDATE employee_records SET position='Busfahrer',business_area='Fahrdienst',employment='Vollzeit',hours=39 WHERE employee_id=?`).bind(r.employee_id).run();await env.DB.prepare(`UPDATE employee_training SET graduated_at=? WHERE employee_id=?`).bind(grad,r.employee_id).run()}}}
let personnelAutomationDay="";async function ensurePersonnelAutomation(env,force=false){let today=new Date(),key=dateKey(today);if(!force&&personnelAutomationDay===key)return;await ensureStaticBirthdaysAndRetirement(env);let y=today.getUTCFullYear();for(const cy of [y-2,y-1,y])await createAutomaticCohort(env,cy,8);await processApprenticeGraduations(env,today);await hydrateEmployees(env,true);personnelAutomationDay=key}
async function hydrateEmployees(env,force=false){if(!force&&Date.now()-employeeHydrationAt<10000)return;let [rr,lr,tr]=await Promise.all([env.DB.prepare(`SELECT * FROM employee_records ORDER BY employee_id`).all(),env.DB.prepare(`SELECT * FROM employee_lifecycle`).all(),env.DB.prepare(`SELECT * FROM employee_training`).all()]),life=new Map((lr.results||[]).map(x=>[x.employee_id,x])),training=new Map((tr.results||[]).map(x=>[x.employee_id,x]));for(const row of rr.results||[]){let e=EMP_BY_ID.get(row.employee_id);if(!e){e={id:row.employee_id,dynamic:true};DATA.employees.push(e);EMP_BY_ID.set(e.id,e)}e.name=row.name;e.first=row.first_name;e.last=row.last_name;e.position=row.position;e.bereich=row.business_area;e.standort=row.location;e.employment=row.employment;e.hours=Number(row.hours||39);e.birthDate=row.birth_date||e.birthDate||"";e.startDate=row.start_date||e.startDate||"";e.dynamic=true;EMP_BY_USER.set(usernameFor(e),e)}for(const e of DATA.employees){let l=life.get(e.id);if(l){e.birthDate=l.birth_date||e.birthDate||"";e.startDate=l.start_date||e.startDate||"";e.endDate=l.end_date||"";e.endReason=l.end_reason||""}else{e.endDate=e.endDate||""}if(!e.birthDate)e.birthDate=autoBirthDateForEmployee(e);if(!e.endDate&&e.birthDate){e.endDate=retirementDateFor(e.birthDate);e.endReason="Rente"}let t=training.get(e.id);if(t){e.apprenticeCohort=Number(t.cohort_year);e.trainingProgram=t.program;e.graduatedAt=t.graduated_at||"";let yr=apprenticeshipYearForDate(e,new Date());if(yr>=1&&yr<=3){e.position=`Auszubildende/r Fachkraft im Fahrbetrieb · ${yr}. Lehrjahr`;e.bereich="Ausbildung";e.employment="Ausbildung"}else if(yr===4){e.position="Busfahrer";e.bereich="Fahrdienst";e.employment="Vollzeit"}}}employeeHydrationAt=Date.now()}

async function uniqueUsername(emp,env){let base=usernameFor(emp),u=base,n=2;for(;;){let db=await env.DB.prepare(`SELECT employee_id FROM users WHERE username=?`).bind(u).first(),mapped=EMP_BY_USER.get(u);if(!db&&(!mapped||mapped.id===emp.id))return u;u=`${base}.${n++}`}}
